svg.script:
const fuzzyValueName="COG";
const fuzzySampleCounts=[3,3,3,3,3];
const fuzzyLowers=[0,0,0,0,0];
const fuzzySteps=[25,50,50,50,25];
const fuzzyNames=["Indoor Temp","Humidity","CO2 Index","Occupancy","Outside Temp"];
const fuzzyCogValues=[
15,15,15,0,0,0,0,0,86,36,36,36,50,50,50,50,
50,63,33,33,33,86,86,86,86,86,86,15,15,15,0,0,
0,0,0,86,36,36,36,50,50,50,50,50,63,33,33,33,
86,86,86,86,86,86,36,36,36,50,50,50,50,50,63,36,
36,36,50,50,50,50,50,63,49,49,49,63,63,63,63,63,
63,0,0,0,50,50,50,0,0,86,50,50,50,50,50,50,
50,50,63,86,86,86,65,65,65,86,86,86,16,16,16,36,
36,36,16,16,65,50,50,50,50,50,50,50,50,63,86,86,
86,65,65,65,86,86,86,50,50,50,50,50,50,50,50,63,
50,50,50,50,50,50,50,50,63,63,63,63,63,63,63,63,
63,63,86,86,86,86,86,86,86,86,86,63,63,63,63,63,
63,63,63,63,86,86,86,86,86,86,86,86,86,86,86,86,
86,86,86,86,86,86,63,63,63,63,63,63,63,63,63,86,
86,86,86,86,86,86,86,86,63,63,63,63,63,63,63,63,
63,63,63,63,63,63,63,63,63,63,63,63,63,63,63,63,
63,63,63
];
const fuzzyMinCog=0;
const fuzzyMaxCog=86;
const fuzzyCogRange=Math.max(fuzzyMaxCog-fuzzyMinCog,1e-12);
const fuzzyDimensionCount=5;
const fuzzyXCount=3;
const fuzzyYCount=3;
const fuzzyCellCount=9;
function fuzzyColour(cog){
  let ratio=(cog-fuzzyMinCog)/fuzzyCogRange;
  ratio=Math.max(0,Math.min(1,ratio));
  let r,g,b;
  if(ratio<0.33){
    const local=ratio/0.33;
    r=37;
    g=Math.round(99+local*132);
    b=235;
  }else if(ratio<0.66){
    const local=(ratio-0.33)/0.33;
    r=Math.round(37+local*213);
    g=Math.round(231+local*13);
    b=Math.round(235-local*194);
  }else{
    const local=(ratio-0.66)/0.34;
    r=Math.round(250-local*11);
    g=Math.round(244-local*176);
    b=Math.round(41-local*27);
  }
  return 'rgb('+r+','+g+','+b+')';
}
function fuzzyPointIndex(indices){
  let point=indices[0];
  for(let d=1;d<fuzzyDimensionCount;d++){
    point=point*fuzzySampleCounts[d]+indices[d];
  }
  return point;
}
function fuzzyInterpolatedCog(x,y,positions){
  const sliderDimensions=fuzzyDimensionCount-2;

  if(sliderDimensions<=0){
    return fuzzyCogValues[fuzzyPointIndex([x,y])];
  }

  const lowerIndices=[];
  const upperIndices=[];
  const fractions=[];

  for(let local=0;local<sliderDimensions;local++){
    const dimension=local+2;
    const maximum=fuzzySampleCounts[dimension]-1;
    const position=Math.max(0,Math.min(maximum,positions[local]));

    const lower=Math.floor(position);
    const upper=Math.min(lower+1,maximum);

    lowerIndices.push(lower);
    upperIndices.push(upper);
    fractions.push(position-lower);
  }

  const cornerCount=Math.pow(2,sliderDimensions);
  let result=0;

  for(let corner=0;corner<cornerCount;corner++){
    const indices=new Array(fuzzyDimensionCount).fill(0);

    indices[0]=x;
    indices[1]=y;

    let weight=1;

    for(let local=0;local<sliderDimensions;local++){
      const useUpper=((corner>>local)&1)!==0;
      const fraction=fractions[local];
      const dimension=local+2;

      if(useUpper){
        indices[dimension]=upperIndices[local];
        weight*=fraction;
      }else{
        indices[dimension]=lowerIndices[local];
        weight*=1-fraction;
      }
    }

    result+=weight*fuzzyCogValues[fuzzyPointIndex(indices)];
  }

  return result;
}
function fuzzyRenderHeatmap(){
  const positions=[];
  const physicalValues=[];

  for(let d=2;d<fuzzyDimensionCount;d++){
    const slider=document.getElementById('slice-slider-'+d);

    let position=0;

    if(slider){
      position=Number(slider.value);
    }

    const maximum=fuzzySampleCounts[d]-1;

    position=Math.max(0,Math.min(maximum,position));

    const value=fuzzyLowers[d]+position*fuzzySteps[d];

    positions.push(position);
    physicalValues.push(value);

    const label=document.getElementById('slice-value-'+d);

    if(label){
      label.textContent=value.toFixed(4);
    }
  }

  for(let x=0;x<fuzzyXCount;x++){
    for(let y=0;y<fuzzyYCount;y++){
      const cell=x*fuzzyYCount+y;

      const cog=fuzzyInterpolatedCog(x,y,positions);

      const rect=document.getElementById('fuzzy-cell-'+cell);

      const title=document.getElementById('fuzzy-title-'+cell);

      if(rect){
        rect.setAttribute('fill',fuzzyColour(cog));
      }

      if(title){
        let text=fuzzyNames[0]+' = '+(fuzzyLowers[0]+x*fuzzySteps[0]).toFixed(4)+', '+fuzzyNames[1]+' = '+(fuzzyLowers[1]+y*fuzzySteps[1]).toFixed(4);

        for(let local=0;local<physicalValues.length;local++){
          const d=local+2;

          text+=', '+fuzzyNames[d]+' = '+physicalValues[local].toFixed(4);
        }

        title.textContent=text+', '+fuzzyValueName+' = '+cog.toFixed(5);
      }
    }
  }
}
document.getElementById('slice-slider-2').addEventListener('input',fuzzyRenderHeatmap);
document.getElementById('slice-slider-3').addEventListener('input',fuzzyRenderHeatmap);
document.getElementById('slice-slider-4').addEventListener('input',fuzzyRenderHeatmap);
fuzzyRenderHeatmap();
